def solve():
    dH_hyd = step_145(solution_enthalpy_anhydrous=sol_anhyd, solution_enthalpy_hydrated=sol_hyd)['delta_h']
    dfH_anhyd = step_382(delta_h=dH_hyd, balanced_equation="CuSO4(s) + 5H2O(l) -> CuSO4·5H2O(s)", formation_enthalpies={"CuSO4·5H2O(s)": dfH_hyd, "H2O(l)": dfH_h2o_l}, unknown_species="CuSO4(s)")['formation_enthalpy']
    dH_anhyd_decomp = step_141(target_equation="CuSO4(s) -> CuO(s) + SO3(g)", step_equations=[["Cu(s) + S(s) + 2O2(g) -> CuSO4(s)", dfH_anhyd], ["Cu(s) + 1/2O2(g) -> CuO(s)", dfH_cuo], ["S(s) + 3/2O2(g) -> SO3(g)", dfH_so3]])['delta_h']
    dH_decomp = -dH_hyd + dH_anhyd_decomp + 5 * dH_vap_h2o
    return dH_decomp / (dS_decomp / 1000)
